"""A minimal but complete MCP server over stdio, generated by mcp-doctor init.

It speaks newline-delimited JSON-RPC 2.0 on stdin/stdout. Anything printed to
stdout that is not a JSON-RPC frame breaks the transport, so all logging goes to
stderr.
"""

import json
import sys

PROTOCOL_VERSION = "2025-06-18"
SERVER_INFO = {"name": "demo-tools", "version": "1.0.0"}

TOOLS = [
    {
        "name": "add",
        "description": "Add two integers and return the sum.",
        "inputSchema": {
            "type": "object",
            "properties": {
                "a": {"type": "integer", "description": "first addend"},
                "b": {"type": "integer", "description": "second addend"},
            },
            "required": ["a", "b"],
            "additionalProperties": False,
        },
        "outputSchema": {
            "type": "object",
            "properties": {"sum": {"type": "integer"}},
            "required": ["sum"],
        },
        "annotations": {"readOnlyHint": True, "idempotentHint": True},
    },
    {
        "name": "echo",
        "description": "Return the given text unchanged. Useful for transport checks.",
        "inputSchema": {
            "type": "object",
            "properties": {
                "text": {"type": "string", "maxLength": 2000},
                "uppercase": {"type": "boolean", "default": False},
            },
            "required": ["text"],
            "additionalProperties": False,
        },
        "annotations": {"readOnlyHint": True},
    },
    {
        "name": "word_count",
        "description": "Count words and lines in a block of text.",
        "inputSchema": {
            "type": "object",
            "properties": {"text": {"type": "string", "maxLength": 100000}},
            "required": ["text"],
        },
        "annotations": {"readOnlyHint": True, "idempotentHint": True},
    },
]

RESOURCES = [
    {
        "uri": "memo://handbook",
        "name": "Team handbook",
        "description": "Short notes about how the demo team works.",
        "mimeType": "text/markdown",
    }
]

HANDBOOK = """# Demo handbook

- Ship small changes.
- Every tool declares its schema.
- Every error carries a code.
"""


def log(message):
    """All diagnostics go to stderr: stdout belongs to the protocol."""
    print("demo-tools: " + message, file=sys.stderr)
    sys.stderr.flush()


def result(request_id, payload):
    return {"jsonrpc": "2.0", "id": request_id, "result": payload}


def error(request_id, code, message, data=None):
    payload = {"code": code, "message": message}
    if data is not None:
        payload["data"] = data
    return {"jsonrpc": "2.0", "id": request_id, "error": payload}


def call_add(arguments):
    missing = [name for name in ("a", "b") if name not in arguments]
    if missing:
        return None, error(None, -32602, "missing arguments: " + ", ".join(missing))
    if not isinstance(arguments["a"], int) or isinstance(arguments["a"], bool):
        return None, error(None, -32602, "a and b must be integers")
    if not isinstance(arguments["b"], int) or isinstance(arguments["b"], bool):
        return None, error(None, -32602, "a and b must be integers")
    total = arguments["a"] + arguments["b"]
    return {
        "content": [{"type": "text", "text": str(total)}],
        "structuredContent": {"sum": total},
    }, None


def call_echo(arguments):
    text = arguments.get("text")
    if not isinstance(text, str):
        return None, error(None, -32602, "text must be a string")
    if arguments.get("uppercase"):
        text = text.upper()
    return {"content": [{"type": "text", "text": text}]}, None


def call_word_count(arguments):
    text = arguments.get("text")
    if not isinstance(text, str):
        return None, error(None, -32602, "text must be a string")
    words = len(text.split())
    lines = len(text.splitlines()) or 1
    summary = str(words) + " words, " + str(lines) + " lines"
    return {
        "content": [{"type": "text", "text": summary}],
        "structuredContent": {"words": words, "lines": lines},
    }, None


HANDLERS = {"add": call_add, "echo": call_echo, "word_count": call_word_count}


def handle(request):
    method = request.get("method")
    request_id = request.get("id")
    params = request.get("params") or {}
    if method == "initialize":
        return result(
            request_id,
            {
                "protocolVersion": PROTOCOL_VERSION,
                "capabilities": {"tools": {}, "resources": {}},
                "serverInfo": SERVER_INFO,
                "instructions": "Small demo server for mcp-doctor. Try the add tool.",
            },
        )
    if method == "ping":
        return result(request_id, {})
    if method == "tools/list":
        return result(request_id, {"tools": TOOLS})
    if method == "resources/list":
        return result(request_id, {"resources": RESOURCES})
    if method == "resources/templates/list":
        return result(request_id, {"resourceTemplates": []})
    if method == "resources/read":
        uri = params.get("uri")
        if uri != "memo://handbook":
            return error(request_id, -32602, "unknown resource " + repr(uri))
        return result(
            request_id,
            {
                "contents": [
                    {
                        "uri": "memo://handbook",
                        "mimeType": "text/markdown",
                        "text": HANDBOOK,
                    }
                ]
            },
        )
    if method == "tools/call":
        name = params.get("name")
        handler = HANDLERS.get(name)
        if handler is None:
            return error(request_id, -32602, "unknown tool " + repr(name))
        payload, failure = handler(params.get("arguments") or {})
        if failure is not None:
            failure["id"] = request_id
            return failure
        return result(request_id, payload)
    return error(request_id, -32601, "method not found: " + repr(method))


def main():
    """Read newline-delimited JSON-RPC frames until stdin closes."""
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            request = json.loads(line)
        except json.JSONDecodeError as exc:
            response = error(None, -32700, "parse error: " + exc.msg)
            sys.stdout.write(json.dumps(response) + chr(10))
            sys.stdout.flush()
            continue
        if not isinstance(request, dict) or request.get("jsonrpc") != "2.0":
            request_id = request.get("id") if isinstance(request, dict) else None
            response = error(request_id, -32600, "invalid request")
            sys.stdout.write(json.dumps(response) + chr(10))
            sys.stdout.flush()
            continue
        if "id" not in request:
            log("notification " + str(request.get("method")))
            continue
        response = handle(request)
        sys.stdout.write(json.dumps(response) + chr(10))
        sys.stdout.flush()


if __name__ == "__main__":
    main()
